 b={'block_id':f'BLK-EX-{n}','block_type':kind,'heading':title,'text':text,'claim_ids':[cid],'context_tags':[],'assessment_objectives':['B'],'claims_seen':{cid:1}};b['authored_hash']=hashlib.sha256(_artefact_text(b).encode()).hexdigest();blocks.append(b)
